/**
 * Crafty Rose Social Studio — server entry points.
 *
 * Phase 1: serves the app shell, sets up the database spreadsheet and
 * returns dashboard data (clearly flagged as SAMPLE until real
 * platform connections exist in Phase 3).
 */

var APP = {
  name: 'Crafty Rose Social Studio',
  version: '0.1.0',
  timeZone: 'America/Halifax',
  siteUrl: 'https://studio.craftyrosegifts.ca'
};

/** Web app entry point. */
function doGet() {
  var tpl = HtmlService.createTemplateFromFile('Index');
  tpl.siteUrl = APP.siteUrl;
  return tpl.evaluate()
    .setTitle(APP.name)
    .setFaviconUrl(APP.siteUrl + '/rose64.png')
    .addMetaTag('viewport', 'width=device-width, initial-scale=1')
    .setXFrameOptionsMode(HtmlService.XFrameOptionsMode.DEFAULT);
}

/** Lets HTML templates pull in other HTML files: <?!= include('Styles') ?> */
function include(name) {
  return HtmlService.createHtmlOutputFromFile(name).getContent();
}

/**
 * Called by the interface on load. Makes sure the database exists,
 * then returns everything the shell and dashboard need.
 */
function getAppBootstrap() {
  var db = Db.ensure();
  return {
    app: { name: APP.name, version: APP.version, timeZone: APP.timeZone },
    user: { email: Session.getActiveUser().getEmail() },
    database: { url: db.getUrl(), ready: true },
    now: new Date().toISOString(),
    dashboard: SampleData.dashboard()
  };
}

/** Run once from the editor (or let the app call it) to create the database. */
function setup() {
  var db = Db.ensure();
  Logger.log('Database ready: ' + db.getUrl());
}

/**
 * Crafty Rose Social Studio — database layer.
 *
 * Application data lives in a private Google Sheet ("Crafty Rose Studio — Data")
 * inside the "Crafty Rose Social Studio" Drive folder. One tab per table.
 *
 * Security: access tokens are NEVER written to the spreadsheet. They are kept in
 * Apps Script's private property store (see Phase 3), which only this script can read.
 */

var DB_SCHEMA = {
  Posts: [
    'id', 'title', 'postType', 'status', 'baseCaption', 'baseHashtags', 'link',
    'mediaIds', 'scheduledAt', 'timeZone', 'inQueue', 'notes', 'createdAt', 'updatedAt'
  ],
  // One row per platform for each post, so every platform has its own caption,
  // settings and publishing status (e.g. Instagram published, TikTok failed → retry TikTok only).
  PostTargets: [
    'id', 'postId', 'platform', 'accountId', 'format', 'caption', 'hashtags', 'title',
    'description', 'destinationUrl', 'coverMediaId', 'mediaIds', 'options', 'status',
    'scheduledAt', 'publishedAt', 'platformPostId', 'platformUrl', 'attempts',
    'lastError', 'lastAttemptAt', 'createdAt', 'updatedAt'
  ],
  Media: [
    'id', 'fileName', 'driveFileId', 'folder', 'tags', 'kind', 'mimeType', 'sizeBytes',
    'width', 'height', 'aspectRatio', 'durationSec', 'container', 'videoCodec',
    'audioCodec', 'frameRate', 'thumbnailFileId', 'compatibility', 'parentMediaId',
    'isOriginal', 'uploadedAt', 'notes'
  ],
  Accounts: [
    'id', 'platform', 'accountName', 'username', 'externalId', 'status', 'scopes',
    'capabilities', 'connectedAt', 'lastSyncAt', 'lastError', 'notes'
  ],
  Captions: [
    'id', 'title', 'category', 'body', 'hashtagGroupId', 'platforms', 'timesUsed',
    'createdAt', 'updatedAt'
  ],
  HashtagGroups: ['id', 'name', 'category', 'hashtags', 'createdAt', 'updatedAt'],
  AccountMetrics: [
    'id', 'date', 'platform', 'accountId', 'followers', 'reach', 'views', 'engagements',
    'likes', 'comments', 'shares', 'saves', 'videoViews', 'capturedAt'
  ],
  PostMetrics: [
    'id', 'targetId', 'platform', 'capturedAt', 'views', 'reach', 'likes', 'comments',
    'shares', 'saves', 'videoViews', 'watchTimeSec'
  ],
  ActivityLog: [
    'id', 'timestamp', 'level', 'type', 'postId', 'targetId', 'platform', 'message', 'details'
  ],
  Settings: ['key', 'value', 'updatedAt']
};

var MEDIA_FOLDERS = [
  'Product Photography', 'Tumblers and Drinkware', 'Apparel', 'Personalized Gifts',
  'Seasonal Products', 'Christmas', 'Behind the Scenes', 'Videos and Reels',
  'General Marketing'
];

var DEFAULT_SETTINGS = {
  timeZone: 'America/Halifax',
  brandLightGreen: '#8BC4A9',
  brandDarkGreen: '#4C6D5E',
  defaultPublishTime: '10:00',
  schemaVersion: '1'
};

var Db = (function () {
  var PROP_DB = 'DB_SPREADSHEET_ID';
  var PROP_ROOT = 'DRIVE_ROOT_FOLDER_ID';
  var cached = null;

  function props() { return PropertiesService.getScriptProperties(); }

  function tryOpen(id) {
    if (!id) return null;
    try { return SpreadsheetApp.openById(id); } catch (e) { return null; }
  }

  // Drive access uses the Drive REST API with the narrow "drive.file" permission,
  // so the studio can only see the files and folders it created itself.
  var Drive = {
    req: function (method, path, body, query) {
      var url = 'https://www.googleapis.com/drive/v3/' + path;
      if (query) {
        url += '?' + Object.keys(query).map(function (k) {
          return encodeURIComponent(k) + '=' + encodeURIComponent(query[k]);
        }).join('&');
      }
      var res = UrlFetchApp.fetch(url, {
        method: method,
        contentType: 'application/json',
        payload: body ? JSON.stringify(body) : undefined,
        headers: { Authorization: 'Bearer ' + ScriptApp.getOAuthToken() },
        muteHttpExceptions: true
      });
      var code = res.getResponseCode();
      if (code >= 300) throw new Error('Drive API ' + code + ': ' + res.getContentText().slice(0, 300));
      var text = res.getContentText();
      return text ? JSON.parse(text) : {};
    },
    exists: function (id) {
      if (!id) return false;
      try { return !Drive.req('get', 'files/' + id, null, { fields: 'id,trashed' }).trashed; }
      catch (e) { return false; }
    },
    folder: function (name, parentId) {
      var q = "mimeType='application/vnd.google-apps.folder' and trashed=false and name='" +
        name.replace(/'/g, "\\'") + "'" + (parentId ? " and '" + parentId + "' in parents" : '');
      var found = Drive.req('get', 'files', null, { q: q, fields: 'files(id)', pageSize: 1 }).files;
      if (found && found.length) return found[0].id;
      var body = { name: name, mimeType: 'application/vnd.google-apps.folder' };
      if (parentId) body.parents = [parentId];
      return Drive.req('post', 'files', body, { fields: 'id' }).id;
    },
    move: function (fileId, parentId) {
      var cur = Drive.req('get', 'files/' + fileId, null, { fields: 'parents' }).parents || [];
      Drive.req('patch', 'files/' + fileId, {}, { addParents: parentId, removeParents: cur.join(','), fields: 'id' });
    },
    copy: function (fileId, name, parentId) {
      return Drive.req('post', 'files/' + fileId + '/copy', { name: name, parents: [parentId] }, { fields: 'id' }).id;
    },
    children: function (parentId) {
      return Drive.req('get', 'files', null, {
        q: "'" + parentId + "' in parents and trashed=false",
        fields: 'files(id,name,createdTime)', orderBy: 'createdTime desc', pageSize: 100
      }).files || [];
    },
    trash: function (fileId) { Drive.req('patch', 'files/' + fileId, { trashed: true }, { fields: 'id' }); }
  };

  /** Creates (once) the studio's Drive folders and returns their IDs. */
  function ensureFolders() {
    var p = props();
    var rootId = p.getProperty(PROP_ROOT);
    var ready = p.getProperty('DRIVE_FOLDERS_READY') === String(MEDIA_FOLDERS.length);
    if (ready && Drive.exists(rootId)) {
      return { root: rootId, backups: p.getProperty('DRIVE_BACKUPS_FOLDER_ID'), media: p.getProperty('DRIVE_MEDIA_FOLDER_ID') };
    }
    if (!Drive.exists(rootId)) {
      rootId = Drive.folder('Crafty Rose Social Studio', null);
      p.setProperty(PROP_ROOT, rootId);
    }
    var backups = Drive.folder('Backups', rootId);
    var media = Drive.folder('Media Library', rootId);
    MEDIA_FOLDERS.forEach(function (name) { Drive.folder(name, media); });
    p.setProperties({
      DRIVE_BACKUPS_FOLDER_ID: backups,
      DRIVE_MEDIA_FOLDER_ID: media,
      DRIVE_FOLDERS_READY: String(MEDIA_FOLDERS.length)
    });
    return { root: rootId, backups: backups, media: media };
  }

  function ensureSheets(ss) {
    Object.keys(DB_SCHEMA).forEach(function (name) {
      var headers = DB_SCHEMA[name];
      var sh = ss.getSheetByName(name) || ss.insertSheet(name);
      var current = sh.getLastColumn() > 0
        ? sh.getRange(1, 1, 1, sh.getLastColumn()).getValues()[0] : [];
      // Add any missing columns at the end (safe schema upgrades, never deletes data).
      var missing = headers.filter(function (h) { return current.indexOf(h) === -1; });
      if (current.length === 0) {
        sh.getRange(1, 1, 1, headers.length).setValues([headers]);
      } else if (missing.length) {
        sh.getRange(1, current.length + 1, 1, missing.length).setValues([missing]);
      }
      var width = Math.max(current.length + missing.length, headers.length);
      sh.getRange(1, 1, 1, width)
        .setFontWeight('bold').setBackground('#EAF3EE').setFontColor('#3D5A4D');
      sh.setFrozenRows(1);
    });
    var stray = ss.getSheetByName('Sheet1');
    if (stray && ss.getSheets().length > 1) ss.deleteSheet(stray);
  }

  function ensureSettings(ss) {
    var sh = ss.getSheetByName('Settings');
    var rows = sh.getLastRow() > 1 ? sh.getRange(2, 1, sh.getLastRow() - 1, 1).getValues() : [];
    var keys = rows.map(function (r) { return r[0]; });
    var now = new Date().toISOString();
    Object.keys(DEFAULT_SETTINGS).forEach(function (k) {
      if (keys.indexOf(k) === -1) sh.appendRow([k, DEFAULT_SETTINGS[k], now]);
    });
  }

  function ensure() {
    if (cached) return cached;
    var lock = LockService.getScriptLock();
    lock.waitLock(20000);
    try {
      var ss = tryOpen(props().getProperty(PROP_DB));
      var folders = ensureFolders();
      if (!ss) {
        ss = SpreadsheetApp.create('Crafty Rose Studio — Data');
        Drive.move(ss.getId(), folders.root);
        props().setProperty(PROP_DB, ss.getId());
        ss.setSpreadsheetTimeZone(APP.timeZone);
      }
      ensureSheets(ss);
      ensureSettings(ss);
      cached = ss;
      return ss;
    } finally {
      lock.releaseLock();
    }
  }

  /** Read a whole table as an array of objects. */
  function all(table) {
    var sh = ensure().getSheetByName(table);
    var last = sh.getLastRow();
    if (last < 2) return [];
    var values = sh.getRange(1, 1, last, sh.getLastColumn()).getValues();
    var headers = values.shift();
    return values.map(function (row) {
      var o = {};
      headers.forEach(function (h, i) { o[h] = row[i]; });
      return o;
    });
  }

  /** Append a row object to a table; returns the object with id/timestamps. */
  function insert(table, obj) {
    var sh = ensure().getSheetByName(table);
    var headers = sh.getRange(1, 1, 1, sh.getLastColumn()).getValues()[0];
    var now = new Date().toISOString();
    if (headers.indexOf('id') !== -1 && !obj.id) obj.id = Utilities.getUuid();
    if (headers.indexOf('createdAt') !== -1 && !obj.createdAt) obj.createdAt = now;
    if (headers.indexOf('updatedAt') !== -1) obj.updatedAt = now;
    sh.appendRow(headers.map(function (h) {
      var v = obj[h];
      return (v !== null && typeof v === 'object') ? JSON.stringify(v) : (v === undefined ? '' : v);
    }));
    return obj;
  }

  /** Append an entry to the activity log. */
  function log(level, type, message, extra) {
    extra = extra || {};
    return insert('ActivityLog', {
      timestamp: new Date().toISOString(), level: level, type: type, message: message,
      postId: extra.postId || '', targetId: extra.targetId || '',
      platform: extra.platform || '', details: extra.details || ''
    });
  }

  /** Copy the database into Drive › Crafty Rose Social Studio › Backups (keeps the latest 8). */
  function backup() {
    var ss = ensure();
    var folders = ensureFolders();
    var stamp = Utilities.formatDate(new Date(), APP.timeZone, 'yyyy-MM-dd HHmm');
    var name = 'Studio backup ' + stamp;
    SpreadsheetApp.flush();
    Drive.copy(ss.getId(), name, folders.backups);
    Drive.children(folders.backups).slice(8).forEach(function (f) { Drive.trash(f.id); });
    log('success', 'backup', 'Database backed up (' + stamp + ')');
    return { ok: true, name: name };
  }

  return { ensure: ensure, all: all, insert: insert, log: log, backup: backup };
})();

/** Exposed to the interface: Settings › "Back up now". */
function backupDatabase() { return Db.backup(); }

/**
 * SAMPLE DATA — for designing the dashboard in Phase 1 only.
 *
 * Nothing here comes from a real social media account. Every response carries
 * `isSample: true` and the interface shows a clear "Sample data" label.
 * This file is removed/bypassed once real accounts are connected (Phase 3–4).
 */

var SampleData = (function () {

  function seeded(seed) {
    var s = seed;
    return function () { s = (s * 9301 + 49297) % 233280; return s / 233280; };
  }

  function isoInDays(days, hour, minute) {
    var d = new Date();
    d.setDate(d.getDate() + days);
    d.setHours(hour, minute || 0, 0, 0);
    return d.toISOString();
  }

  function engagementSeries(n) {
    var rnd = seeded(42);
    var out = [];
    var base = 140;
    for (var i = n - 1; i >= 0; i--) {
      var d = new Date(); d.setDate(d.getDate() - i);
      var weekend = (d.getDay() === 0 || d.getDay() === 6) ? 35 : 0;
      base += (rnd() - 0.42) * 14;
      out.push({ date: Utilities.formatDate(d, APP.timeZone, 'yyyy-MM-dd'),
                 value: Math.max(40, Math.round(base + weekend + rnd() * 40)) });
    }
    return out;
  }

  function dashboard() {
    var platforms = [
      { id: 'instagram', name: 'Instagram', handle: '@craftyrosegifts', followers: 1248, change: 3.4 },
      { id: 'tiktok',    name: 'TikTok',    handle: '@craftyrosegifts', followers: 2310, change: 6.1 },
      { id: 'facebook',  name: 'Facebook',  handle: 'Crafty Rose Gifts', followers: 862,  change: 1.2 },
      { id: 'pinterest', name: 'Pinterest', handle: '@craftyrosegifts', followers: 397,  change: 2.8 },
      { id: 'youtube',   name: 'YouTube',   handle: '@craftyrosegifts', followers: 184,  change: 4.5 }
    ];
    var series = engagementSeries(90);
    var last30 = series.slice(-30).reduce(function (a, p) { return a + p.value; }, 0);
    var prev30 = series.slice(-60, -30).reduce(function (a, p) { return a + p.value; }, 0);

    return {
      isSample: true,
      generatedAt: new Date().toISOString(),
      totals: {
        followers: platforms.reduce(function (a, p) { return a + p.followers; }, 0),
        followersChange: 3.9,
        scheduled: 7,
        publishedThisMonth: 11,
        engagement30: last30,
        engagementChange: Math.round(((last30 - prev30) / prev30) * 1000) / 10
      },
      platforms: platforms,
      engagementSeries: series,
      upcoming: [
        { id: 'p1', title: 'Teacher appreciation tumblers', caption: 'Personalized tumblers for the teachers who make every day brighter 🍎 Order by Friday for…', type: 'photo', category: 'drinkware', platforms: ['instagram', 'facebook'], scheduledAt: isoInDays(1, 10, 30), status: 'scheduled' },
        { id: 'p2', title: 'Ornament making — behind the scenes', caption: 'A peek at how each Christmas ornament gets its name ✨', type: 'video', category: 'christmas', platforms: ['instagram', 'tiktok', 'youtube', 'facebook'], scheduledAt: isoInDays(2, 18, 0), status: 'scheduled' },
        { id: 'p3', title: 'Custom name hoodies restock', caption: 'They’re back! Cozy custom hoodies in five new colours…', type: 'photo', category: 'apparel', platforms: ['instagram', 'facebook', 'pinterest'], scheduledAt: isoInDays(4, 12, 0), status: 'scheduled' },
        { id: 'p4', title: 'Holiday craft fair announcement', caption: 'Come see us this weekend! Booth details and fair hours inside 🎄', type: 'photo', category: 'event', platforms: ['facebook', 'instagram'], scheduledAt: isoInDays(5, 9, 0), status: 'attention' },
        { id: 'p5', title: 'Gift guide: under $30', caption: 'Thoughtful handmade gifts that won’t break the bank…', type: 'carousel', category: 'gifts', platforms: ['pinterest', 'instagram'], scheduledAt: isoInDays(7, 19, 30), status: 'draft' }
      ],
      activity: [
        { level: 'success', platform: 'instagram', message: 'Reel “Vinyl pressing in slow motion” published', at: isoInDays(0, 9, 2) },
        { level: 'error',   platform: 'tiktok',    message: 'TikTok upload failed — connection expired. Reconnect TikTok and retry.', at: isoInDays(-1, 18, 1) },
        { level: 'success', platform: 'facebook',  message: 'Post “Fall mug collection” published', at: isoInDays(-1, 12, 0) },
        { level: 'warning', platform: 'instagram', message: 'Craft fair post needs a cover image before it can be scheduled', at: isoInDays(-2, 16, 40) },
        { level: 'success', platform: 'pinterest', message: 'Pin “Personalized wine tumblers” published', at: isoInDays(-3, 20, 15) }
      ]
    };
  }

  return { dashboard: dashboard };
})();
